import { test, expect } from '@playwright/test';

test.describe('Notification Visual Distinction', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should display unread notifications with distinct styling', async ({ page }) => {
    const unreadNotification = await page.getByRole('listitem', { name: 'Unread Notification' });
    const readNotification = await page.getByRole('listitem', { name: 'Read Notification' });

    const unreadStyle = await unreadNotification.evaluate(element => window.getComputedStyle(element).backgroundColor);
    const readStyle = await readNotification.evaluate(element => window.getComputedStyle(element).backgroundColor);

    expect(unreadStyle).not.toEqual(readStyle);
    expect(unreadStyle).toMatch(/rgba?\(255, 0, 0/); // Example: Expecting unread notifications to have a red background
  });

  test('should mark notifications as read when clicked', async ({ page }) => {
    const unreadNotification = await page.getByRole('listitem', { name: 'Unread Notification' });

    await unreadNotification.click();

    const updatedNotification = await page.getByRole('listitem', { name: 'Unread Notification' });
    const updatedStyle = await updatedNotification.evaluate(element => window.getComputedStyle(element).backgroundColor);

    expect(updatedStyle).toMatch(/rgba?\(0, 255, 0/); // Example: Expecting read notifications to have a green background
  });
});
